#include <stdio.h>

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;
    int opp[1000][7];
    int contrib[1000][7];
    for (int i = 0; i < N; i++) {
        int A, B, C, D, E, F;
        scanf("%d %d %d %d %d %d", &A, &B, &C, &D, &E, &F);
        opp[i][A] = F;
        opp[i][F] = A;
        opp[i][B] = D;
        opp[i][D] = B;
        opp[i][C] = E;
        opp[i][E] = C;
        for (int v = 1; v <= 6; v++) {
            int other = opp[i][v];
            int max = 0;
            for (int k = 1; k <= 6; k++) {
                if (k != v && k != other) {
                    if (k > max) max = k;
                }
            }
            contrib[i][v] = max;
        }
    }
    int ans = 0;
    for (int x = 1; x <= 6; x++) {
        int total = contrib[0][x];
        int b = x;
        for (int i = 1; i < N; i++) {
            total += contrib[i][b];
            b = opp[i][b];
        }
        if (total > ans) ans = total;
    }
    printf("%d\n", ans);
    return 0;
}
